<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Solar System Simulation</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body { background: #030308; overflow: hidden; }
    canvas { display: block; }
  </style>
</head>
<body>
<canvas id="space"></canvas>

<script>
  const canvas = document.getElementById('space');
  const ctx = canvas.getContext('2d');

  let width, height, cx, cy, scale;

  const planets = [
    { name: 'Mercury', distance: 55,  radius: 3.5, color: '#a8a8a8', speed: 0.035, angle: Math.random() * 6 },
    { name: 'Venus',   distance: 85,  radius: 6.0, color: '#e3bb76', speed: 0.025, angle: Math.random() * 6 },
    { name: 'Earth',   distance: 125, radius: 6.5, color: '#4ba3e3', speed: 0.018, angle: Math.random() * 6 },
    { name: 'Mars',    distance: 165, radius: 4.8, color: '#d14f2c', speed: 0.014, angle: Math.random() * 6 },
    { name: 'Jupiter', distance: 225, radius: 13.0, color: '#caa57a', speed: 0.009, angle: Math.random() * 6 },
    { name: 'Saturn',  distance: 285, radius: 10.5, color: '#e0c885', speed: 0.006, angle: Math.random() * 6, hasRing: true },
    { name: 'Uranus',  distance: 345, radius: 8.0, color: '#7fe3e8', speed: 0.004, angle: Math.random() * 6 },
    { name: 'Neptune', distance: 395, radius: 7.8, color: '#3d6fe8', speed: 0.003, angle: Math.random() * 6 }
  ];

  let stars = [];
  function createStars() {
    stars = [];
    const count = Math.floor((width * height) / 3000);
    for (let i = 0; i < count; i++) {
      stars.push({
        x: Math.random() * width,
        y: Math.random() * height,
        r: Math.random() * 1.5 + 0.3,
        alpha: Math.random() * 0.8 + 0.2,
        twinkleSpeed: Math.random() * 0.02 + 0.005
      });
    }
  }

  function resize() {
    width = canvas.width = window.innerWidth;
    height = canvas.height = window.innerHeight;
    cx = width / 2;
    cy = height / 2;
    scale = Math.min(width, height) / 880;
    createStars();
  }

  window.addEventListener('resize', resize);
  resize();

  function drawStars() {
    ctx.save();
    for (let star of stars) {
      star.alpha += star.twinkleSpeed;
      if (star.alpha > 1 || star.alpha < 0.2) star.twinkleSpeed *= -1;
      ctx.fillStyle = `rgba(255, 255, 255, ${Math.max(0.1, star.alpha)})`;
      ctx.beginPath();
      ctx.arc(star.x, star.y, star.r, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();
  }

  function drawSun() {
    const sunRadius = 24 * scale;

    const glow = ctx.createRadialGradient(cx, cy, 0, cx, cy, sunRadius * 3);
    glow.addColorStop(0, 'rgba(255, 220, 100, 1)');
    glow.addColorStop(0.3, 'rgba(255, 140, 20, 0.4)');
    glow.addColorStop(1, 'rgba(255, 100, 0, 0)');
    ctx.fillStyle = glow;
    ctx.beginPath();
    ctx.arc(cx, cy, sunRadius * 3, 0, Math.PI * 2);
    ctx.fill();

    const core = ctx.createRadialGradient(cx - sunRadius * 0.2, cy - sunRadius * 0.2, 0, cx, cy, sunRadius);
    core.addColorStop(0, '#fff5cc');
    core.addColorStop(0.5, '#ffcc00');
    core.addColorStop(1, '#ff6600');
    ctx.fillStyle = core;
    ctx.beginPath();
    ctx.arc(cx, cy, sunRadius, 0, Math.PI * 2);
    ctx.fill();

    ctx.font = `${Math.max(10, 11 * scale)}px system-ui, sans-serif`;
    ctx.fillStyle = '#ffe099';
    ctx.textAlign = 'center';
    ctx.fillText('Sun', cx, cy + sunRadius + 14 * scale);
  }

  function animate() {
    ctx.fillStyle = '#030308';
    ctx.fillRect(0, 0, width, height);

    drawStars();
    drawSun();

    planets.forEach(p => {
      const dist = p.distance * scale;
      const radius = Math.max(2, p.radius * scale);

      // Orbit path
      ctx.beginPath();
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.08)';
      ctx.lineWidth = 1;
      ctx.arc(cx, cy, dist, 0, Math.PI * 2);
      ctx.stroke();

      // Planet position
      const px = cx + Math.cos(p.angle) * dist;
      const py = cy + Math.sin(p.angle) * dist;

      // Saturn's rings
      if (p.hasRing) {
        ctx.save();
        ctx.translate(px, py);
        ctx.rotate(0.4);
        ctx.beginPath();
        ctx.ellipse(0, 0, radius * 2.2, radius * 0.7, 0, 0, Math.PI * 2);
        ctx.strokeStyle = 'rgba(224, 200, 133, 0.6)';
        ctx.lineWidth = 2.5 * scale;
        ctx.stroke();
        ctx.restore();
      }

      // Planet body
      ctx.save();
      ctx.shadowColor = p.color;
      ctx.shadowBlur = 8 * scale;
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(px, py, radius, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();

      // Label
      ctx.font = `${Math.max(9, 10 * scale)}px system-ui, sans-serif`;
      ctx.fillStyle = 'rgba(220, 225, 240, 0.85)';
      ctx.textAlign = 'center';
      ctx.fillText(p.name, px, py - radius - 6 * scale);

      // Advance orbit
      p.angle += p.speed * 0.5;
    });

    requestAnimationFrame(animate);
  }

  animate();
</script>
</body>
</html>
```

The script runs a `requestAnimationFrame` loop that clears a fullscreen `<canvas>`, updates twinkling star background particles, renders circular orbit tracks around a radiant Sun, and advances each planet's orbital angle using trigonometry to calculate and draw its position, rings, and name label.
